const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const section=$('.technology-sequence'),art=$('.tech-art'),canvas=$('#fluid-scene');let manualUntil=0,chapter=-1,paused=false;let progress=0,mouse={x:0,y:0},renderer=null,render3D=null,visible=false,raf=0,last=0,initializing=false;
all('.technology .accordion summary').forEach(summary=>summary.addEventListener('click',()=>manualUntil=performance.now()+15000));
function measure(){const r=section.getBoundingClientRect();progress=Math.max(0,Math.min(1,-r.top/Math.max(1,r.height-innerHeight)));if(innerWidth<701)progress=Math.max(0,Math.min(1,(innerHeight-art.getBoundingClientRect().top)/(innerHeight+art.offsetHeight)));}
let motionFrame=0;function update(){motionFrame=0;measure();if(!reducedMotion){const podium=$('.product-podium'),pr=$('.product-story').getBoundingClientRect(),pp=Math.max(0,Math.min(1,-pr.top/Math.max(1,pr.height-innerHeight)));podium.style.transform=`perspective(1200px) rotateY(${Math.sin(pp*Math.PI*2)*10}deg) translateY(${Math.sin(pp*Math.PI*3)*-8}px)`;
const tr=$('.distributor').getBoundingClientRect(),tp=Math.max(0,Math.min(1,(innerHeight-tr.top)/(innerHeight+tr.height)));$('.distributor-vehicle').style.transform=`translateX(${(tp-.5)*160}px)`;
const gr=$('.global').getBoundingClientRect(),gp=Math.max(0,Math.min(1,(innerHeight-gr.top)/(innerHeight*.85)));$('.globe-wrap').style.transform=`perspective(1400px) rotateY(${(1-gp)*-16}deg) translateY(${(1-gp)*55}px) scale(${.88+gp*.12})`;
const cr=$('.contact').getBoundingClientRect(),cp=Math.max(0,Math.min(1,(innerHeight-cr.top)/(innerHeight+cr.height)));all('.contact-collection img').forEach((img,i)=>{img.style.transform=`translate3d(${(cp-.5)*(i-1)*40}px,${Math.sin(cp*Math.PI+i*.4)*-20}px,${i===1?60:0}px) rotateZ(${(i-1)*7+(cp-.5)*5}deg)`});
all('.journal-image img').forEach(img=>{const r=img.parentElement.getBoundingClientRect(),p=Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight+r.height)));img.style.transform=`scale(1.12) translateY(${(p-.5)*-22}px)`})}start3D();}
addEventListener('scroll',()=>{if(!motionFrame)motionFrame=requestAnimationFrame(update)},{passive:true});addEventListener('resize',()=>{if(!motionFrame)motionFrame=requestAnimationFrame(update)},{passive:true});
all('.family-card').forEach(card=>{card.addEventListener('pointermove',e=>{if(reducedMotion||e.pointerType!=='mouse')return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1600px) rotateY(${x*10}deg) rotateX(${-y*8}deg) translateZ(12px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});
const pauseButton=$('.gear-pause');pauseButton.addEventListener('click',()=>{paused=!paused;pauseButton.setAttribute('aria-pressed',String(paused));pauseButton.textContent=paused?'Resume motion':'Pause motion';start3D()});
canvas.addEventListener('pointermove',e=>{if(reducedMotion)return;const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width-.5;mouse.y=(e.clientY-r.top)/r.height-.5;start3D()});canvas.addEventListener('pointerleave',()=>{mouse.x=mouse.y=0;start3D()});
function frame(time){raf=0;if(!visible||document.hidden||!render3D)return;if(!reducedMotion&&time-last<15){raf=requestAnimationFrame(frame);return}last=time;measure();const next=Math.min(2,Math.floor(progress*3));if(!reducedMotion&&innerWidth>700&&performance.now()>manualUntil&&next!==chapter){chapter=next;all('.technology .accordion details').forEach((details,i)=>details.open=i===chapter);$('.fluid-caption span').textContent=['01 / THE OIL FILM','02 / PRECISION IN MOTION','03 / CONTINUOUS PROTECTION'][chapter]}render3D(time,progress,mouse,paused);if(!reducedMotion)raf=requestAnimationFrame(frame)}function start3D(){if(visible&&render3D&&!raf){last=performance.now()-35;raf=requestAnimationFrame(frame)}}
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible){if(!initializing){initializing=true;initialize()}start3D()}else if(raf){cancelAnimationFrame(raf);raf=0}},{rootMargin:'150px',threshold:0}).observe(art);
async function initialize(){try{const {mountGearScene}=await import('./gear-scene.js');render3D=await mountGearScene(canvas,reducedMotion);$('.technology').classList.add('fluid-ready');canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();$('.technology').classList.remove('fluid-ready');render3D=null;if(raf)cancelAnimationFrame(raf);raf=0});start3D()}catch(e){$('.technology').classList.remove('fluid-ready')}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(raf)cancelAnimationFrame(raf);raf=0}else start3D()});update();
